import java.util.*;

public class e {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int testCount = 1;
        while (testCount-- > 0) {
            int totalCount = sc.nextInt();
            int[] firstArray = new int[3];
            int[] secondArray = new int[3];
            for (int i = 0; i < 3; i++) {
                firstArray[i] = sc.nextInt();
            }
            for (int i = 0; i < 3; i++) {
                secondArray[i] = sc.nextInt();
            }
            int minSum1 = 0;
            for (int i = 0; i < 3; i++) {
                minSum1 += Math.min(firstArray[i], secondArray[i] + secondArray[(i + 2) % 3]);
            }
            System.out.print((totalCount - minSum1) + " ");
            int minSum2 = 0;
            for (int i = 0; i < 3; i++) {
                minSum2 += Math.min(firstArray[i], secondArray[(i + 1) % 3]);
            }
            System.out.println(minSum2);
        }
    }
}
